import app from 'flarum/admin/app';
/** Why a sync did not finish: the server's own message, or a run still going after the wait. */
export class SyncFailed extends Error {
  constructor(serverMessage, timedOut) {
    if (serverMessage === void 0) {
      serverMessage = null;
    }
    if (timedOut === void 0) {
      timedOut = false;
    }
    super(serverMessage || 'sync failed');
    this.serverMessage = serverMessage;
    this.timedOut = timedOut;
  }
}

/** Polls every 2 seconds for up to 5 minutes. */
const POLL_MS = 2000;
const MAX_POLLS = 150;
const apiUrl = () => app.forum.attribute('apiUrl') + '/picks';

/**
 * Start an admin sync and resolve with its result once it has run.
 *
 * The server queues every sync and answers 202 at once; `task` names the
 * status to poll. An answer that is not "queued" or "running" (a team with a
 * custom crest, say) is returned as it is, without polling.
 */
export default function runSync(startPath, task, body) {
  return app.request({
    method: 'POST',
    url: apiUrl() + startPath,
    body
  }).then(started => {
    if (started && started.status !== 'queued' && started.status !== 'running') return started;
    return poll(task, 0);
  });
}
function poll(task, attempt) {
  return app.request({
    method: 'GET',
    url: `${apiUrl()}/sync/${task}/status`
  }).then(state => {
    if (state.status === 'done') return state.result || {};
    if (state.status === 'failed') throw new SyncFailed(state.result?.message ?? null);
    if (attempt >= MAX_POLLS) throw new SyncFailed(null, true);
    return new Promise((resolve, reject) => {
      setTimeout(() => poll(task, attempt + 1).then(resolve, reject), POLL_MS);
    });
  });
}
flarum.reg.add('ernestdefoe-picks', 'admin/utils/runSync', runSync);